/bin/bash -lc "python3 - <<'PY'
import hashlib, re, subprocess
from pathlib import Path
commit='b01bcd297b8063699f0f321e3ef17485f399b0ee'
p='scripts/comparator/expected/palomar/Challenge.lean.expected'
raw=subprocess.check_output(['git','show',f'{commit}:{p}'])
print('Pinned artifact:',len(raw.splitlines()),len(raw),hashlib.sha256(raw).hexdigest())
print('Working artifact equals pinned:',Path(p).read_bytes()==raw)
def strip_comments(s):
    out=[]; i=0; level=0; string=False
    while i<len(s):
        if level:
            if s.startswith('/-',i): level+=1; i+=2
            elif s.startswith('-/',i): level-=1; i+=2
            else:
                if s[i]=='\\n': out.append('\\n')
                i+=1
        elif string:
            out.append(s[i])
            if s[i]=='\\\\' and i+1<len(s): i+=1; out.append(s[i])
            elif s[i]=='\"': string=False
            i+=1
        elif s.startswith('/-',i): level=1; out.append(' '); i+=2
        elif s.startswith('--',i):
            j=s.find('\\n',i); i=len(s) if j<0 else j
        else:
            out.append(s[i]); string=s[i]=='\"'; i+=1
    assert not level
    return ''.join(out)
def normalize(s): return ' '.join(strip_comments(s).split())
source_paths=list(Path('MIPStarRE/QPBT/Palomar').glob('*.lean'))+[Path('MIPStarRE/LDT/Basic/ParametersBase.lean'),Path('MIPStarRE/QPBT/Algebra/FieldBasis.lean'),Path('MIPStarRE/QPBT/Algebra/QuditQubit.lean')]
source_paths=[s for s in source_paths if s.exists()]
# Include any other original source file defining the retained field accessors.
for s in Path('MIPStarRE/QPBT/Algebra').glob('*.lean'):
    if 'binaryCoordinates' in s.read_text() and s not in source_paths: source_paths.append(s)
sources={str(s): normalize(subprocess.check_output(['git','show',f'{commit}:{s}']).decode()) for s in source_paths}
clean=strip_comments(raw.decode())
starts=list(re.finditer(r'(?m)"'^(?:(?:noncomputable )?(?:def|abbrev|structure|class|inductive|instance|theorem)'"\\b|attribute\\b|namespace\\b|end\\b)',clean))
checked=0; unmatched=[]; holes=[]
for n,m in enumerate(starts):
    block=clean[m.start():starts[n+1].start() if n+1<len(starts) else len(clean)].strip()
    if block.startswith(('namespace','end','attribute')): continue
    header=block.splitlines()[0]
    if re.search(r'\\bsorry\\b',block):
        holes.append(header)
        if 'fixedFieldModel' in header: continue
        block=block[:block.index(':= by')]
    norm=' '.join(block.split())
    hits=[path for path,src in sources.items() if norm in src]
    if hits: checked+=1
    else: unmatched.append(header)
print('Declarations/target headers matched to pinned library source:',checked)
print('Unmatched blocks:',unmatched)
print('Hole-bearing declarations:',holes)
print('Bypass tokens:',re.findall(r'\\b(?:axiom|admit|native_decide|unsafeCast|unsafeCoerce|lcProof|ofReduceBool|ofReduceNat)\\b',clean))
PY"

